BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP104-1-25',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第4條之1（中低收入戶最低生活費1.5倍），該條最後修正公布日 2010-12-29，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP104-1-31',$swsi$考試時點法規核對（逐條人工核對）：本題考全民健康保險法第10條（第五類被保險人為社會救助法之低收入戶成員），該條最後修正公布日 2011-01-26，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0060001'),('SP104-2-24',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第5條之1第1項第1款第2目（失業或參加職訓期間得不計算工作收入），該條最後修正公布日 2013-01-30，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-1-01',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第12條（低收入戶成員增加補助情形），該條最後修正公布日 2010-12-29，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-1-16',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第21條（急難救助情形），該條最後修正公布日 2010-12-29，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-1-40',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第11條、第15條（生活扶助現金給付；以工代賑屬就業服務），該條最後修正公布日 2015-12-30（考試前公布並施行），本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-2-17',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第10條（受理申請五日內派員調查），該條最後修正公布日 2005-01-19，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-2-18',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第5條之1（未就業者工作收入不予列計情形），該條最後修正公布日 2013-01-30，本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP105-2-27',$swsi$考試時點法規核對（逐條人工核對）：本題考社會救助法第11條（現金給付金額每四年調整），並比對第4條、第15條、第16條之2，該條最後修正公布日 2015-12-30（考試前公布並施行），本題考試日 2016-07-23 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP106-1-24',$swsi$考試時點法規核對（逐條人工核對）：本題考法規位階（法律須經立法院三讀，「校園性侵害性騷擾或性霸凌防治準則」為行政規則），不受個別條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP106-1-38',$swsi$考試時點法規核對（逐條人工核對）：本題考立法沿革（1980年通過老人福利法、殘障福利法、社會救助法），屬歷史事實，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP110-1-07',$swsi$考試時點法規核對（逐條人工核對）：本題考立法沿革（1980年通過老人福利法、殘障福利法、社會救助法），屬歷史事實，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP110-1-34',$swsi$考試時點法規核對（逐條人工核對）：本題考特殊境遇家庭扶助條例第2條（扶助項目），該條自制定以來未曾修正（考試前 2021-01-20 的修正只涉及第12條），考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文及法規沿革（2026-11-24 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050075');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>13 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>13 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status='verified_current', legal_checked_at='2026-11-24T20:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-24T20:00:00+00:00'::timestamptz)<>'abae6ff3d9f1665d1f49da45f291027a' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_13, count(*) total_13 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
